use std::{static_assert, append::Append};
use super::{SSFP_ADJUST_DERIVED, SSFP_ADJUST_INV_PARAMS, SSFP_ADJUST_SQRT_PARAMS};
use super::{SSFP_ADJUST_EXP_PARAMS, SSFP_ADJUST_LN_PARAMS, SSFP_CHECK_SETUP};
use super::ssfp::{SSFP, SSFP_MATRIX, SSFP_METADATA};
use super::{WHOLE_BITS, DECIMAL_BITS, PRIORITY_MODE, RESET_ROUND, INV_ROUND};
use super::{ZERO_AWARE_COMP, INV_PRECISION_LVL, LAZY_ZERO_ADJUST, LN_LAZY_BOUNDS};


// Globals for SSFP Context
pub(crate) comptime mut global SSFP_CTX_EXISTS: bool = false;
comptime mut global INTERIM_COUNT: Field = 0;
comptime mut global SSFP_CONTEXT: CtString = "";
comptime mut global SSFP_OUTPUTS: [CtString] = [];
comptime mut global SSFP_OUTPUT_LVLS: [Option<u32>] = [];
comptime mut global SSFP_OUTPUT_MDS: [Option<SSFP_METADATA>] = [];

pub comptime struct SSFP_CTX_CONFIG{
    pub CTX_PRIORITY_MODE: u32,
    pub CTX_ZERO_AWARE_COMP: bool,
    pub CTX_RESET_ROUND: bool,
    pub CTX_INV_ROUND: bool,
    pub CTX_INV_PRECISION_LVL: u32,
    pub CTX_LAZY_ZERO_ADJUST: bool,
    pub CTX_LN_LAZY_BOUNDS: bool
}

comptime fn SSFP_CTX_CLEAR(){
    SSFP_CONTEXT = "";
    SSFP_OUTPUTS = [];
    SSFP_OUTPUT_LVLS = [];
    SSFP_OUTPUT_MDS = [];
}
pub comptime fn SSFP_CTX_UPDATE(CONF: SSFP_CTX_CONFIG){
    if !SSFP_CTX_EXISTS{
        static_assert(false, "Context not initialized");
    }
    PRIORITY_MODE = CONF.CTX_PRIORITY_MODE;
    ZERO_AWARE_COMP = CONF.CTX_ZERO_AWARE_COMP;
    RESET_ROUND = CONF.CTX_RESET_ROUND;
    INV_ROUND = CONF.CTX_INV_ROUND;
    INV_PRECISION_LVL = CONF.CTX_INV_PRECISION_LVL;
    LAZY_ZERO_ADJUST = CONF.CTX_LAZY_ZERO_ADJUST;
    LN_LAZY_BOUNDS = CONF.CTX_LN_LAZY_BOUNDS;
    SSFP_ADJUST_DERIVED();
    SSFP_ADJUST_INV_PARAMS();
    SSFP_ADJUST_SQRT_PARAMS();
    SSFP_ADJUST_EXP_PARAMS();
    SSFP_ADJUST_LN_PARAMS();
    SSFP_CHECK_SETUP();
}
pub comptime fn SSFP_CTX_INIT_CUSTOM(CTX_WHOLE_BITS: u32, CTX_DECIMAL_BITS: u32, CONF: SSFP_CTX_CONFIG){
    if SSFP_CTX_EXISTS{
        static_assert(false, "Multiple context initialization detected");
    }
    SSFP_CTX_EXISTS = true;
    WHOLE_BITS = CTX_WHOLE_BITS;
    DECIMAL_BITS = CTX_DECIMAL_BITS;
    SSFP_CTX_UPDATE(CONF);
    SSFP_CTX_CLEAR();
}
pub comptime fn SSFP_CTX_INIT(){
    SSFP_CTX_INIT_CUSTOM(32, 16, 
    SSFP_CTX_CONFIG{
        CTX_PRIORITY_MODE:      0,
        CTX_ZERO_AWARE_COMP:    false,
        CTX_RESET_ROUND:        false,
        CTX_INV_ROUND:          false,
        CTX_INV_PRECISION_LVL:  1,
        CTX_LAZY_ZERO_ADJUST:   false,
        CTX_LN_LAZY_BOUNDS:     false
    });
}
pub comptime fn SSFP_CTX_DUMP(CTX_PRINT: bool) -> Quoted{
    if !SSFP_CTX_EXISTS{
        static_assert(false, "Context not initialized");
    }
    SSFP_CTX_EXISTS = false;
    if CTX_PRINT{
        SSFP_PRINT_CTX();
    }
    SSFP_CONTEXT = "";
    SSFP_OUTPUTS = [];
    quote{}
}
pub comptime fn SSFP_CTX_SOLVE(CTX_PRINT: bool) -> Quoted{
    if !SSFP_CTX_EXISTS{
        static_assert(false, "Context not initialized");
    }
    SSFP_CTX_EXISTS = false;
    if CTX_PRINT{
        SSFP_PRINT_CTX();
    }
    let mut res: CtString = "";
    let OUTPUT_LENG: u32 = SSFP_OUTPUTS.len();
    if OUTPUT_LENG == 1{
        let v: CtString = SSFP_OUTPUTS[0];
        res = SSFP_CONTEXT.append(f"{v}");
    }else{
        let mut v_all: CtString = "";
        for i in 0..(OUTPUT_LENG-1){
            let v_i: CtString = SSFP_OUTPUTS[i];
            v_all = v_all.append(f"{v_i}, ");
        }
        let v_L: CtString = SSFP_OUTPUTS[OUTPUT_LENG-1];
        v_all = v_all.append(f"{v_L}");
        res = SSFP_CONTEXT.append(f"[{v_all}]");
    }
    SSFP_CONTEXT = "";
    SSFP_OUTPUTS = [];
    f"{res}".quoted_contents()
}

pub comptime fn SSFP_PUSH_OUTPUT<T>(s: T) where T: Solvable{
    if !SSFP_CTX_EXISTS{
        static_assert(false, "Context not initialized");
    }
    SSFP_OUTPUT_LVLS = SSFP_OUTPUT_LVLS.push_back(s.get_lvl());
    SSFP_OUTPUT_MDS = SSFP_OUTPUT_MDS.push_back(s.get_md());
    SSFP_OUTPUTS = SSFP_OUTPUTS.push_back(s.get_ctstr());
}
pub comptime fn SSFP_PUSH_OUTPUTS<T, let N: u32>(arr_s: [T; N]) where T: Solvable{
    if !SSFP_CTX_EXISTS{
        static_assert(false, "Context not initialized");
    }
    for s in arr_s{
        SSFP_OUTPUT_LVLS = SSFP_OUTPUT_LVLS.push_back(s.get_lvl());
        SSFP_OUTPUT_MDS = SSFP_OUTPUT_MDS.push_back(s.get_md());
        SSFP_OUTPUTS = SSFP_OUTPUTS.push_back(s.get_ctstr());
    }
}
pub comptime fn SSFP_PRINT_CTX(){
    println(SSFP_CONTEXT);
    println(SSFP_OUTPUTS);
}
pub comptime fn SSFP_GET_OUT_LVLS() -> [Option<u32>]{
    SSFP_OUTPUT_LVLS
}
pub comptime fn SSFP_GET_OUT_LVLS_FORCE() -> [u32]{
    SSFP_OUTPUT_LVLS.map(|o_l| o_l.unwrap())
}
pub comptime fn SSFP_GET_OUT_MDS() -> [Option<SSFP_METADATA>]{
    SSFP_OUTPUT_MDS
}




comptime fn get_v() -> CtString{
    f"_{INTERIM_COUNT}"
}
pub comptime fn append_ctx_code(cts: CtString){
    SSFP_CONTEXT = SSFP_CONTEXT.append(cts);
}
pub comptime fn append_ctx_nl(){
    append_ctx_code("\n");
}
pub comptime fn append_ctx_println(cts: CtString){
    append_ctx_code(f"println({cts});\n");
}
pub comptime fn append_ctx_code_q(q: Quoted){
    append_ctx_code(f"{q}\n");
}
pub comptime fn append_ctx_var_Field(cts: CtString) -> CtString{
    let var_name = get_v();
    append_ctx_code(f"let {var_name}: Field = {cts};\n");
    INTERIM_COUNT += 1;
    var_name
}
pub comptime fn append_ctx_var_MutField(cts: CtString) -> CtString{
    let var_name = get_v();
    append_ctx_code(f"let mut {var_name}: Field = {cts};\n");
    INTERIM_COUNT += 1;
    var_name
}
pub comptime fn append_ctx_Var(var_type: CtString, cts: CtString) -> CtString{
    let var_name = get_v();
    append_ctx_code(f"let {var_name}: {var_type} = {cts};\n");
    INTERIM_COUNT += 1;
    var_name
}
pub comptime fn append_ctx_MutVar(var_type: CtString, cts: CtString) -> CtString{
    let var_name = get_v();
    append_ctx_code(f"let mut {var_name}: {var_type} = {cts};\n");
    INTERIM_COUNT += 1;
    var_name
}





pub(crate) trait Solvable {
    comptime fn get_lvl(self) -> Option<u32>;
    comptime fn get_md(self) -> Option<SSFP_METADATA>;
    comptime fn get_ctstr(self) -> CtString;
}

impl Solvable for SSFP {
    comptime fn get_lvl(self) -> Option<u32> {
        Option::some(self.lvl)
    }
    comptime fn get_md(self) -> Option<SSFP_METADATA> {
        Option::some(self.md)
    }
    comptime fn get_ctstr(self) -> CtString {
        self.v
    }
}
impl Solvable for SSFP_MATRIX {
    comptime fn get_lvl(self) -> Option<u32> {
        Option::some(self.lvl)
    }
    comptime fn get_md(self) -> Option<SSFP_METADATA> {
        Option::some(self.md)
    }
    comptime fn get_ctstr(self) -> CtString {
        self.mat
    }
}
impl Solvable for CtString {
    comptime fn get_lvl(self) -> Option<u32> {
        Option::none()
    }
    comptime fn get_md(self) -> Option<SSFP_METADATA> {
        Option::none()
    }
    comptime fn get_ctstr(self) -> CtString {
        self
    }
}






